INSERT INTO station (nodeid, nodename, citycode, cityname, node_address) SELECT v.nodeid, v.nodename, v.citycode, v.cityname, v.node_address FROM ( VALUES
(#{st.nodeid}, #{st.nodename}, #{st.citycode}, #{st.cityname}, #{st.nodeAddress})
) AS v(nodeid, nodename, citycode, cityname, node_address) WHERE NOT EXISTS ( SELECT 1 FROM station s WHERE s.nodename = v.nodename AND s.nodeid <> v.nodeid ) ON CONFLICT (nodeid) DO UPDATE SET nodename = EXCLUDED.nodename, citycode = EXCLUDED.citycode, cityname = EXCLUDED.cityname, node_address = EXCLUDED.node_address
